"""Byte-oriented helpers shared by the command line search implementation."""
import os
import sys

class UserError(Exception):
    pass

def bstr(s):
    return s if isinstance(s, bytes) else s.encode('utf-8', 'surrogateescape')

def ustr(s):
    return s.decode('utf-8', 'surrogateescape') if isinstance(s, bytes) else s

def diagnostic(text):
    try:
        sys.stderr.buffer.write(b'rg: ' + bstr(text) + b'\n')
    except (BrokenPipeError, OSError):
        pass

def os_error(err):
    descriptions = {1:'Operation not permitted', 2:'No such file or directory', 5:'Input/output error',
                    13:'Permission denied', 20:'Not a directory', 21:'Is a directory', 22:'Invalid argument',
                    24:'Too many open files', 40:'Too many levels of symbolic links'}
    return '{} (os error {})'.format(descriptions.get(err.errno, err.strerror), err.errno)

def unescape_bytes(s):
    """Unescape the byte escapes recognized by the output separator flags."""
    raw = bstr(s)
    out = bytearray()
    i = 0
    table = {ord('a'):7, ord('b'):8, ord('e'):27, ord('f'):12, ord('n'):10,
             ord('r'):13, ord('t'):9, ord('v'):11, ord('0'):0, ord('\\'):92}
    while i < len(raw):
        if raw[i] != 92 or i + 1 == len(raw):
            out.append(raw[i]); i += 1; continue
        c = raw[i+1]
        if c in table:
            out.append(table[c]); i += 2
        elif c == ord('x') and i+3 < len(raw):
            try:
                out.append(int(raw[i+2:i+4], 16)); i += 4
            except ValueError:
                out.extend(raw[i:i+2]); i += 2
        else:
            out.extend(raw[i:i+2]); i += 2
    return bytes(out)
