        raise ValueError("invalid color spec format: '{}'. Valid format is '(path|line|column|match):(fg|bg|style):(value)'.".format(s))
    dest,attr=parts[:2]
    if dest not in ('path','line','column','match'):
        raise ValueError("unrecognized output type '{}'. Choose from: path, line, column, match.".format(dest))
    if attr not in ('fg','bg','style','none'):
        raise ValueError("unrecognized spec type '{}'. Choose from: fg, bg, style, none.".format(attr))
    if attr == 'none': return (dest,attr,None)
    value=parts[2]
