    except OSError:return False

def transcode(data,encoding):
    if encoding=='none':return data
    if data.startswith(b'\xef\xbb\xbf'):return data[3:] if encoding=='auto' else data[3:].decode('utf-8','replace').encode('utf-8')
    if data.startswith(b'\xff\xfe'):return data[2:].decode('utf-16-le','replace').encode('utf-8')
    if data.startswith(b'\xfe\xff'):return data[2:].decode('utf-16-be','replace').encode('utf-8')
