    if encoding=='x-user-defined':return ''.join(chr(x) if x<128 else chr(0xF780+x-128) for x in data).encode('utf-8')
    try:return data.decode(encoding,'replace').encode('utf-8')
    except (LookupError,UnicodeError):return data

