                    raw=sys.stdin.buffer.read();read_stdin=True
                else:
                    try:
                        with open(value,'rb') as f:raw=f.read()
                    except OSError as e:raise UserError('{}: {}'.format(value,os_error(e)))
                raw=transcode(raw,'auto')
                if raw:
                    rows=raw.split(b'\n')
                    if rows[-1]==b'':rows.pop()
                    for line in rows:
                        if line.endswith(b'\r'):line=line[:-1]
                        try:patterns.append(line.decode('utf-8'))
                        except UnicodeDecodeError as e:raise UserError('{}: pattern is not valid UTF-8'.format(value))
        paths=list(opt.paths)
    else:
        if not opt.paths:raise UserError('ripgrep requires at least one pattern to execute a search')
        patterns=[opt.paths[0]];paths=opt.paths[1:]
    implicit=False
    if not paths:
        if not read_stdin and stdin_available():paths=['-']
        else:paths=['.'];implicit=True
